def gen_numbers():
    yield from range(1, 11)

def filter_even(gen):
    for x in gen:
        if x % 2 == 0:
            yield x

def square(gen):
    for x in gen:
        yield x ** 2

pipeline = square(filter_even(gen_numbers()))
list(pipeline)  # [4, 16, 36, 64, 100]

