def coroutine(func):
    @wraps(func)
    def primer(*args, **kwargs):
        gen = func(*args, **kwargs)
        next(gen)
        return gen
    return primer

@coroutine
def grep(pattern):
    print(f"Ищем {pattern}")
    while True:
        line = yield
        if pattern in line:
            print(line)

g = grep("python")
g.send("hello world")
g.send("python is great")  # python is great
